INSERT INTO existing_system_roles SELECT name FROM roles WHERE name IN ('guest','user','admin','superadmin');
INSERT INTO roles(name,description,is_system) VALUES ('guest','Newly registered, pending approval',1),('user','Standard warehouse operator',1),('admin','Full access including user and role management',1),('superadmin','Unrestricted system access (env-configured)',1) ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,p FROM roles CROSS JOIN unnest(ARRAY['design:read','design:create','design:update','design:delete','preset:read','preset:create','preset:update','preset:delete','accurate:read','accurate:create','accurate:update','accurate:delete','accurate_account:read','accurate_account:create','accurate_account:update','accurate_account:delete','user:read','user:create','user:update','user:delete','role:read','role:create','role:update','role:delete','system:read']) p WHERE name='admin' AND name NOT IN (SELECT name FROM existing_system_roles) ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,p FROM roles CROSS JOIN unnest(ARRAY['design:read','preset:read','accurate:read','accurate:create','accurate:update','accurate:delete','system:read']) p WHERE name='user' AND name NOT IN (SELECT name FROM existing_system_roles) ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission) SELECT id,p FROM roles CROSS JOIN unnest(ARRAY['accurate_account:read','accurate_account:create','accurate_account:update','accurate_account:delete']) p WHERE name='admin' AND NOT EXISTS(SELECT 1 FROM migration_markers WHERE name='accurate_account_permissions_v1') ON CONFLICT DO NOTHING;
INSERT INTO migration_markers(name) VALUES ('accurate_account_permissions_v1') ON CONFLICT DO NOTHING;
